// Montage — Wayland's colour management for the HDR viewer on Linux: wp_color_manager_v1 (wayland-protocols'
// staging color-management-v1, 1.41 or later), its client code generated by wayland-scanner at build time. A surface
// is described to the compositor as BT.2100 PQ or HLG in BT.2020 primaries with the picture's mastering light, and the
// description the compositor prefers for it (its output's reference white and peak) is read back, and again whenever
// it changes, for the viewer's roll-off. Its objects live on an event queue of their own, dispatched by the caller on
// the GUI thread, so Qt's own handling of the connection is left alone. Built where wayland-client, wayland-scanner and
// the protocol are found (MONTAGE_WAYLAND_COLOR); plain C++ around libwayland-client.
#pragma once

#ifdef MONTAGE_WAYLAND_COLOR

#include <cstdint>
#include <memory>
#include <string>

#include "render/ColorSpace.h"
#include "render/HdrView.h"

struct wl_display;
struct wl_surface;

namespace montage {

class WaylandColor {
public:
    // What the compositor prefers for the surface (wp_image_description_info_v1), in nits; 0 where it did not say.
    struct Preferred {
        bool known = false;
        uint32_t tf = 0;  // wp_color_manager_v1.transfer_function, 0 if given otherwise
        double minNits = 0, maxNits = 0, referenceNits = 0, targetMaxNits = 0, targetMaxCll = 0;
    };
    // The surface's image description: BT.2100 PQ or HLG, BT.2020 primaries, and its light.
    struct Description {
        Transfer transfer = Transfer::Pq;
        HdrSurfaceLight light;
        bool operator==(const Description&) const = default;
    };

    // Binds the compositor's colour manager, if it has one (`available`), and reads what it supports.
    explicit WaylandColor(wl_display* display);
    ~WaylandColor();
    WaylandColor(const WaylandColor&) = delete;
    WaylandColor& operator=(const WaylandColor&) = delete;

    bool available() const;
    // Why a BT.2100 surface cannot be described (empty if it can): parametric descriptions, PQ, BT.2020.
    std::string unsupported() const;
    bool supportsHlg() const;
    // The protocol's features as it lists them, for the log.
    std::string features() const;

    // Starts on a surface (Qt's wl_surface for the window): its colour management and feedback objects, and the
    // preferred description read at once. A surface made again (the window hidden and shown) is attached again; the
    // old one is let go first. False if the connection failed.
    bool attach(wl_surface* surface);
    void detach();
    wl_surface* surface() const;

    // Makes the description and, once the compositor has it ready, sets it on the surface (applied at the surface's
    // next commit, the next frame). False, with the compositor's reason, if it failed.
    bool describe(const Description& description, std::string* error = nullptr);
    const Description* described() const;

    const Preferred& preferred() const;
    // Handles what arrived on the queue; true if the preferred description changed (it is read again then).
    bool dispatch();

    struct State;  // (the protocol's objects, in WaylandColor.cpp)

private:
    std::unique_ptr<State> s_;
};

}  // namespace montage

#endif
